/*  Page views and average page views per user (only users with ≥1 purchase in Nov-2020)  */
WITH purchasers AS (
    /* 1.  All Nov-2020 users that made at least one purchase */
    SELECT DISTINCT "USER_PSEUDO_ID"
    FROM (
        SELECT "USER_PSEUDO_ID" FROM GA4.GA4_OBFUSCATED_SAMPLE_ECOMMERCE."EVENTS_20201101" WHERE "EVENT_NAME" = 'purchase' UNION ALL
        SELECT "USER_PSEUDO_ID" FROM GA4.GA4_OBFUSCATED_SAMPLE_ECOMMERCE."EVENTS_20201102" WHERE "EVENT_NAME" = 'purchase' UNION ALL
        SELECT "USER_PSEUDO_ID" FROM GA4.GA4_OBFUSCATED_SAMPLE_ECOMMERCE."EVENTS_20201103" WHERE "EVENT_NAME" = 'purchase' UNION ALL
        SELECT "USER_PSEUDO_ID" FROM GA4.GA4_OBFUSCATED_SAMPLE_ECOMMERCE."EVENTS_20201104" WHERE "EVENT_NAME" = 'purchase' UNION ALL
        SELECT "USER_PSEUDO_ID" FROM GA4.GA4_OBFUSCATED_SAMPLE_ECOMMERCE."EVENTS_20201105" WHERE "EVENT_NAME" = 'purchase' UNION ALL
        SELECT "USER_PSEUDO_ID" FROM GA4.GA4_OBFUSCATED_SAMPLE_ECOMMERCE."EVENTS_20201106" WHERE "EVENT_NAME" = 'purchase' UNION ALL
        SELECT "USER_PSEUDO_ID" FROM GA4.GA4_OBFUSCATED_SAMPLE_ECOMMERCE."EVENTS_20201107" WHERE "EVENT_NAME" = 'purchase' UNION ALL
        SELECT "USER_PSEUDO_ID" FROM GA4.GA4_OBFUSCATED_SAMPLE_ECOMMERCE."EVENTS_20201108" WHERE "EVENT_NAME" = 'purchase' UNION ALL
        SELECT "USER_PSEUDO_ID" FROM GA4.GA4_OBFUSCATED_SAMPLE_ECOMMERCE."EVENTS_20201109" WHERE "EVENT_NAME" = 'purchase' UNION ALL
        SELECT "USER_PSEUDO_ID" FROM GA4.GA4_OBFUSCATED_SAMPLE_ECOMMERCE."EVENTS_20201110" WHERE "EVENT_NAME" = 'purchase' UNION ALL
        SELECT "USER_PSEUDO_ID" FROM GA4.GA4_OBFUSCATED_SAMPLE_ECOMMERCE."EVENTS_20201111" WHERE "EVENT_NAME" = 'purchase' UNION ALL
        SELECT "USER_PSEUDO_ID" FROM GA4.GA4_OBFUSCATED_SAMPLE_ECOMMERCE."EVENTS_20201112" WHERE "EVENT_NAME" = 'purchase' UNION ALL
        SELECT "USER_PSEUDO_ID" FROM GA4.GA4_OBFUSCATED_SAMPLE_ECOMMERCE."EVENTS_20201113" WHERE "EVENT_NAME" = 'purchase' UNION ALL
        SELECT "USER_PSEUDO_ID" FROM GA4.GA4_OBFUSCATED_SAMPLE_ECOMMERCE."EVENTS_20201114" WHERE "EVENT_NAME" = 'purchase' UNION ALL
        SELECT "USER_PSEUDO_ID" FROM GA4.GA4_OBFUSCATED_SAMPLE_ECOMMERCE."EVENTS_20201115" WHERE "EVENT_NAME" = 'purchase' UNION ALL
        SELECT "USER_PSEUDO_ID" FROM GA4.GA4_OBFUSCATED_SAMPLE_ECOMMERCE."EVENTS_20201116" WHERE "EVENT_NAME" = 'purchase' UNION ALL
        SELECT "USER_PSEUDO_ID" FROM GA4.GA4_OBFUSCATED_SAMPLE_ECOMMERCE."EVENTS_20201117" WHERE "EVENT_NAME" = 'purchase' UNION ALL
        SELECT "USER_PSEUDO_ID" FROM GA4.GA4_OBFUSCATED_SAMPLE_ECOMMERCE."EVENTS_20201118" WHERE "EVENT_NAME" = 'purchase' UNION ALL
        SELECT "USER_PSEUDO_ID" FROM GA4.GA4_OBFUSCATED_SAMPLE_ECOMMERCE."EVENTS_20201119" WHERE "EVENT_NAME" = 'purchase' UNION ALL
        SELECT "USER_PSEUDO_ID" FROM GA4.GA4_OBFUSCATED_SAMPLE_ECOMMERCE."EVENTS_20201120" WHERE "EVENT_NAME" = 'purchase' UNION ALL
        SELECT "USER_PSEUDO_ID" FROM GA4.GA4_OBFUSCATED_SAMPLE_ECOMMERCE."EVENTS_20201121" WHERE "EVENT_NAME" = 'purchase' UNION ALL
        SELECT "USER_PSEUDO_ID" FROM GA4.GA4_OBFUSCATED_SAMPLE_ECOMMERCE."EVENTS_20201122" WHERE "EVENT_NAME" = 'purchase' UNION ALL
        SELECT "USER_PSEUDO_ID" FROM GA4.GA4_OBFUSCATED_SAMPLE_ECOMMERCE."EVENTS_20201123" WHERE "EVENT_NAME" = 'purchase' UNION ALL
        SELECT "USER_PSEUDO_ID" FROM GA4.GA4_OBFUSCATED_SAMPLE_ECOMMERCE."EVENTS_20201124" WHERE "EVENT_NAME" = 'purchase' UNION ALL
        SELECT "USER_PSEUDO_ID" FROM GA4.GA4_OBFUSCATED_SAMPLE_ECOMMERCE."EVENTS_20201125" WHERE "EVENT_NAME" = 'purchase' UNION ALL
        SELECT "USER_PSEUDO_ID" FROM GA4.GA4_OBFUSCATED_SAMPLE_ECOMMERCE."EVENTS_20201126" WHERE "EVENT_NAME" = 'purchase' UNION ALL
        SELECT "USER_PSEUDO_ID" FROM GA4.GA4_OBFUSCATED_SAMPLE_ECOMMERCE."EVENTS_20201127" WHERE "EVENT_NAME" = 'purchase' UNION ALL
        SELECT "USER_PSEUDO_ID" FROM GA4.GA4_OBFUSCATED_SAMPLE_ECOMMERCE."EVENTS_20201128" WHERE "EVENT_NAME" = 'purchase' UNION ALL
        SELECT "USER_PSEUDO_ID" FROM GA4.GA4_OBFUSCATED_SAMPLE_ECOMMERCE."EVENTS_20201129" WHERE "EVENT_NAME" = 'purchase' UNION ALL
        SELECT "USER_PSEUDO_ID" FROM GA4.GA4_OBFUSCATED_SAMPLE_ECOMMERCE."EVENTS_20201130" WHERE "EVENT_NAME" = 'purchase'
    )
),
page_views AS (
    /* 2.  All Nov-2020 page_view events performed by those purchasers */
    SELECT "EVENT_DATE",
           "USER_PSEUDO_ID"
    FROM (
        SELECT "EVENT_DATE","USER_PSEUDO_ID" FROM GA4.GA4_OBFUSCATED_SAMPLE_ECOMMERCE."EVENTS_20201101" WHERE "EVENT_NAME" = 'page_view' UNION ALL
        SELECT "EVENT_DATE","USER_PSEUDO_ID" FROM GA4.GA4_OBFUSCATED_SAMPLE_ECOMMERCE."EVENTS_20201102" WHERE "EVENT_NAME" = 'page_view' UNION ALL
        SELECT "EVENT_DATE","USER_PSEUDO_ID" FROM GA4.GA4_OBFUSCATED_SAMPLE_ECOMMERCE."EVENTS_20201103" WHERE "EVENT_NAME" = 'page_view' UNION ALL
        SELECT "EVENT_DATE","USER_PSEUDO_ID" FROM GA4.GA4_OBFUSCATED_SAMPLE_ECOMMERCE."EVENTS_20201104" WHERE "EVENT_NAME" = 'page_view' UNION ALL
        SELECT "EVENT_DATE","USER_PSEUDO_ID" FROM GA4.GA4_OBFUSCATED_SAMPLE_ECOMMERCE."EVENTS_20201105" WHERE "EVENT_NAME" = 'page_view' UNION ALL
        SELECT "EVENT_DATE","USER_PSEUDO_ID" FROM GA4.GA4_OBFUSCATED_SAMPLE_ECOMMERCE."EVENTS_20201106" WHERE "EVENT_NAME" = 'page_view' UNION ALL
        SELECT "EVENT_DATE","USER_PSEUDO_ID" FROM GA4.GA4_OBFUSCATED_SAMPLE_ECOMMERCE."EVENTS_20201107" WHERE "EVENT_NAME" = 'page_view' UNION ALL
        SELECT "EVENT_DATE","USER_PSEUDO_ID" FROM GA4.GA4_OBFUSCATED_SAMPLE_ECOMMERCE."EVENTS_20201108" WHERE "EVENT_NAME" = 'page_view' UNION ALL
        SELECT "EVENT_DATE","USER_PSEUDO_ID" FROM GA4.GA4_OBFUSCATED_SAMPLE_ECOMMERCE."EVENTS_20201109" WHERE "EVENT_NAME" = 'page_view' UNION ALL
        SELECT "EVENT_DATE","USER_PSEUDO_ID" FROM GA4.GA4_OBFUSCATED_SAMPLE_ECOMMERCE."EVENTS_20201110" WHERE "EVENT_NAME" = 'page_view' UNION ALL
        SELECT "EVENT_DATE","USER_PSEUDO_ID" FROM GA4.GA4_OBFUSCATED_SAMPLE_ECOMMERCE."EVENTS_20201111" WHERE "EVENT_NAME" = 'page_view' UNION ALL
        SELECT "EVENT_DATE","USER_PSEUDO_ID" FROM GA4.GA4_OBFUSCATED_SAMPLE_ECOMMERCE."EVENTS_20201112" WHERE "EVENT_NAME" = 'page_view' UNION ALL
        SELECT "EVENT_DATE","USER_PSEUDO_ID" FROM GA4.GA4_OBFUSCATED_SAMPLE_ECOMMERCE."EVENTS_20201113" WHERE "EVENT_NAME" = 'page_view' UNION ALL
        SELECT "EVENT_DATE","USER_PSEUDO_ID" FROM GA4.GA4_OBFUSCATED_SAMPLE_ECOMMERCE."EVENTS_20201114" WHERE "EVENT_NAME" = 'page_view' UNION ALL
        SELECT "EVENT_DATE","USER_PSEUDO_ID" FROM GA4.GA4_OBFUSCATED_SAMPLE_ECOMMERCE."EVENTS_20201115" WHERE "EVENT_NAME" = 'page_view' UNION ALL
        SELECT "EVENT_DATE","USER_PSEUDO_ID" FROM GA4.GA4_OBFUSCATED_SAMPLE_ECOMMERCE."EVENTS_20201116" WHERE "EVENT_NAME" = 'page_view' UNION ALL
        SELECT "EVENT_DATE","USER_PSEUDO_ID" FROM GA4.GA4_OBFUSCATED_SAMPLE_ECOMMERCE."EVENTS_20201117" WHERE "EVENT_NAME" = 'page_view' UNION ALL
        SELECT "EVENT_DATE","USER_PSEUDO_ID" FROM GA4.GA4_OBFUSCATED_SAMPLE_ECOMMERCE."EVENTS_20201118" WHERE "EVENT_NAME" = 'page_view' UNION ALL
        SELECT "EVENT_DATE","USER_PSEUDO_ID" FROM GA4.GA4_OBFUSCATED_SAMPLE_ECOMMERCE."EVENTS_20201119" WHERE "EVENT_NAME" = 'page_view' UNION ALL
        SELECT "EVENT_DATE","USER_PSEUDO_ID" FROM GA4.GA4_OBFUSCATED_SAMPLE_ECOMMERCE."EVENTS_20201120" WHERE "EVENT_NAME" = 'page_view' UNION ALL
        SELECT "EVENT_DATE","USER_PSEUDO_ID" FROM GA4.GA4_OBFUSCATED_SAMPLE_ECOMMERCE."EVENTS_20201121" WHERE "EVENT_NAME" = 'page_view' UNION ALL
        SELECT "EVENT_DATE","USER_PSEUDO_ID" FROM GA4.GA4_OBFUSCATED_SAMPLE_ECOMMERCE."EVENTS_20201122" WHERE "EVENT_NAME" = 'page_view' UNION ALL
        SELECT "EVENT_DATE","USER_PSEUDO_ID" FROM GA4.GA4_OBFUSCATED_SAMPLE_ECOMMERCE."EVENTS_20201123" WHERE "EVENT_NAME" = 'page_view' UNION ALL
        SELECT "EVENT_DATE","USER_PSEUDO_ID" FROM GA4.GA4_OBFUSCATED_SAMPLE_ECOMMERCE."EVENTS_20201124" WHERE "EVENT_NAME" = 'page_view' UNION ALL
        SELECT "EVENT_DATE","USER_PSEUDO_ID" FROM GA4.GA4_OBFUSCATED_SAMPLE_ECOMMERCE."EVENTS_20201125" WHERE "EVENT_NAME" = 'page_view' UNION ALL
        SELECT "EVENT_DATE","USER_PSEUDO_ID" FROM GA4.GA4_OBFUSCATED_SAMPLE_ECOMMERCE."EVENTS_20201126" WHERE "EVENT_NAME" = 'page_view' UNION ALL
        SELECT "EVENT_DATE","USER_PSEUDO_ID" FROM GA4.GA4_OBFUSCATED_SAMPLE_ECOMMERCE."EVENTS_20201127" WHERE "EVENT_NAME" = 'page_view' UNION ALL
        SELECT "EVENT_DATE","USER_PSEUDO_ID" FROM GA4.GA4_OBFUSCATED_SAMPLE_ECOMMERCE."EVENTS_20201128" WHERE "EVENT_NAME" = 'page_view' UNION ALL
        SELECT "EVENT_DATE","USER_PSEUDO_ID" FROM GA4.GA4_OBFUSCATED_SAMPLE_ECOMMERCE."EVENTS_20201129" WHERE "EVENT_NAME" = 'page_view' UNION ALL
        SELECT "EVENT_DATE","USER_PSEUDO_ID" FROM GA4.GA4_OBFUSCATED_SAMPLE_ECOMMERCE."EVENTS_20201130" WHERE "EVENT_NAME" = 'page_view'
    )
    WHERE "USER_PSEUDO_ID" IN (SELECT "USER_PSEUDO_ID" FROM purchasers)
)
SELECT
    "EVENT_DATE",
    COUNT(*)                                       AS "TOTAL_PAGE_VIEWS",
    COUNT(DISTINCT "USER_PSEUDO_ID")               AS "UNIQUE_USERS",
    COUNT(*)::FLOAT / NULLIF(COUNT(DISTINCT "USER_PSEUDO_ID"),0) 
                                                   AS "AVG_PAGE_VIEWS_PER_USER"
FROM page_views
GROUP BY "EVENT_DATE"
ORDER BY "EVENT_DATE";